// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyoloji temel kavramları ve toplumsal kurumlar (kolay).
const ozSocialscience1Kolay = <(String, String, List<String>, String)>[
  ('Toplumsal olayları, ilişkileri ve kurumları bilimsel yöntemlerle inceleyen bilim dalı hangisidir?', 'Sosyoloji', ['Antropoloji', 'Etnografya', 'Psikoloji'], 'Sosyoloji; toplumu, toplumsal ilişkileri ve kurumları bilimsel yöntemle inceler. Antropoloji insanı kültürel ve biyolojik yönleriyle ele alır.'),
  ('Sosyolojinin inceleme birimi olarak tek tek bireylerden çok neyi esas aldığı söylenebilir?', 'Bireyler arası ilişkileri ve toplumsal yapıyı', ['Bireyin iç dünyasındaki duygu, düşünce ve rüyaları', 'Canlıların genetik özelliklerini', 'Doğal çevrenin fiziksel koşullarını'], 'Sosyoloji bireyi tek başına değil, başkalarıyla kurduğu ilişkiler ve bu ilişkilerin oluşturduğu toplumsal yapı içinde ele alır.'),
  ('"Sosyoloji" sözcüğü Latince "socius" ile Yunanca "logos" sözcüklerinden türetilmiştir. Bu iki kökün anlamları sırasıyla hangisidir?', 'Arkadaş/ortak ve bilim', ['Halk ve yönetim', 'Toplum ile tarih yazımı bilgisi', 'Kent ve düzen'], 'Socius ortak, arkadaş; logos söz, bilim anlamına gelir. Böylece sosyoloji kabaca toplumu oluşturan ilişkilerin bilimi demektir.'),
  ('Sosyolojinin olgulara "olması gereken" değil "olan" açısından yaklaşması onun hangi özelliğini gösterir?', 'Betimleyici ve nesnel olmayı amaçlamasını', ['Ahlaki kurallar koyan normatif bir bilim olmasını', 'Yalnızca geçmiş olaylarla uğraşmasını', 'Doğa bilimlerinin bir alt dalı olmasını'], 'Sosyoloji toplumsal olguları değer yargısı katmadan, olduğu gibi betimleyip açıklamaya çalışır; ahlak kuralı koymaz.'),
  ('Sosyolojide makro düzeyde yapılan bir inceleme için en uygun örnek hangisidir?', 'Sanayileşmenin ülkenin sınıf yapısına etkisi', ['İki yakın arkadaş arasındaki günlük selamlaşma biçimi', 'Bir sınıftaki öğrencilerin oturma düzeni', 'Bir ailenin akşam yemeği sohbetleri'], 'Makro sosyoloji toplumun bütününü, büyük yapıları ve kurumları; mikro sosyoloji ise yüz yüze etkileşimleri inceler.'),
  ('Toplumsal olguları açıklarken "sosyolojik muhayyile" (sosyolojik imgelem) kavramını ortaya atan Amerikalı sosyolog kimdir?', 'C. Wright Mills', ['Talcott Parsons', 'Robert Merton', 'Erving Goffman'], 'C. Wright Mills, 1959\'da yayımlanan Sosyolojik Muhayyile adlı eserinde bireysel sıkıntılarla toplumsal sorunlar arasındaki bağı görme yetisini bu adla tanımlamıştır.'),
  ('Sosyolojinin ayrı bir bilim olarak doğuşunu hazırlayan iki büyük tarihsel olay hangileridir?', 'Sanayi Devrimi ve Fransız İhtilali', ['Haçlı Seferleri ve Coğrafi Keşifler', 'Rönesans ve Reform', 'Kavimler Göçü ve Magna Carta'], '18. ve 19. yüzyılda Sanayi Devrimi ile Fransız İhtilali\'nin yol açtığı büyük toplumsal sarsıntılar, toplumu bilimsel olarak inceleme ihtiyacını doğurmuştur.'),
  ('Sanayi Devrimi\'nin sosyolojinin doğuşuna katkısı en iyi hangi seçenekte açıklanmıştır?', 'Hızlı kentleşme ve işçi sorunlarıyla toplumsal düzenin sorgulanmasına yol açması', ['Kilisenin toplum üzerindeki etkisini artırması', 'Tarım toplumunu güçlendirerek kırsal nüfusu çoğaltması', 'Feodal beylerin siyasal gücünü pekiştirmesi'], 'Fabrikalar, kentlere yoğun göç, çalışma koşulları ve yoksulluk gibi yeni sorunlar toplumsal yapının bilimsel olarak incelenmesini gerekli kılmıştır.'),
  ('Sosyolojinin doğduğu dönemde Avrupa\'da kentlere hızla göç eden kalabalıkların geleneksel bağlarını yitirmesi, düşünürlerin özellikle hangi soruya yönelmesine neden olmuştur?', 'Toplumsal bütünleşme ve düzen nasıl sağlanır?', ['Gezegenlerin yörüngeleri nasıl hesaplanabilir?', 'Tarım ürünleri nasıl artırılır?', 'Bir dilin kökeni nasıl belirlenir?'], 'Geleneksel bağların zayıflaması, toplumu bir arada tutan bağların ne olduğu sorusunu, yani toplumsal düzen ve bütünleşme sorununu öne çıkarmıştır.'),
  ('"Sosyoloji" terimini ilk kez kullanan ve sosyolojinin kurucusu sayılan düşünür kimdir?', 'Auguste Comte', ['Emile Durkheim', 'Herbert Spencer', 'Max Weber'], 'Fransız düşünür Auguste Comte, 1830\'lu yıllarda yazdığı Pozitif Felsefe Dersleri\'nde bu terimi kullanmıştır.'),
  ('Bir toplulukta yıldırım olayının tanrıların öfkesiyle açıklanması, Comte\'un üç hal yasasındaki hangi aşamaya örnektir?', 'Teolojik aşama', ['Metafizik aşama', 'Pozitif aşama', 'Endüstriyel aşama'], 'Olayları doğaüstü varlıkların iradesiyle açıklamak, Comte\'un teolojik aşamasının temel özelliğidir.'),
  ('"Toplumsal olgulara birer şeymiş gibi bakılmalıdır" ilkesini savunan Fransız sosyolog kimdir?', 'Emile Durkheim', ['Auguste Comte', 'Gabriel Tarde', 'Pierre Bourdieu'], 'Durkheim, Sosyolojik Yöntemin Kuralları adlı eserinde toplumsal olguların dışarıdan, nesnel bir gözle incelenmesi gerektiğini savunmuştur.'),
  ('Durkheim\'a göre toplumsal olguların iki temel özelliği hangileridir?', 'Bireyin dışında olmaları ve bireye zorlayıcı etki yapmaları', ['Bireyin iç dünyasından doğmaları ve geçici olmaları', 'Yalnızca ekonomik kaynaklı olmaları ve ölçülememeleri', 'Kalıtımla aktarılmaları ve değişmemeleri'], 'Durkheim\'a göre dil, hukuk ya da gelenek gibi toplumsal olgular bireyden önce vardır, onun dışındadır ve davranışlarını zorlayıcı biçimde biçimlendirir.'),
  ('Gruba aşırı bağlılık nedeniyle bireyin kendini topluluk için feda etmesi, Durkheim\'ın intihar sınıflamasında hangi türe girer?', 'Diğerkâm (alturistik) intihar', ['Egoist intihar', 'Anomik intihar', 'Bireyci (individüalist) intihar'], 'Durkheim\'a göre toplumsal bütünleşmenin aşırı güçlü olduğu durumlarda birey kendi varlığını grubun çıkarı için önemsizleştirir; bu diğerkâm intihardır.'),
  ('Durkheim\'ın "anomi" kavramı en iyi hangi seçenekle karşılanır?', 'Kuralsızlık ya da normların etkisini yitirmesi', ['Toplumsal sınıflar arasındaki sürekli ve şiddetli çatışma', 'Bireyin rolleri arasında kalması', 'Kültürün başka topluma geçmesi'], 'Anomi, toplumsal normların zayıfladığı, belirsizleştiği ve bireyin davranışlarına yön veremediği durumu ifade eder.'),
  ('Kapitalizmin doğuşunu Protestan ahlakıyla ilişkilendiren ünlü eserin yazarı kimdir?', 'Max Weber', ['Karl Marx', 'Georg Simmel', 'Ferdinand Tönnies'], 'Weber, Protestan Ahlakı ve Kapitalizmin Ruhu adlı eserinde Kalvinist çalışma ahlakının kapitalist zihniyetin gelişimine katkısını incelemiştir.'),
  ('Weber\'in "anlayıcı sosyoloji" yaklaşımı toplumsal eylemi incelerken özellikle neye önem verir?', 'Eylemde bulunan bireyin eylemine yüklediği öznel anlama', ['Eylemin yalnızca ölçülebilir fiziksel sonuçlarına', 'Toplumun üretim ilişkilerine', 'Bireylerin biyolojik özelliklerine'], 'Weber\'e göre toplumsal eylemi açıklamak için önce bireylerin o eyleme yükledikleri anlamı kavramak (verstehen) gerekir.'),
  ('Weber\'e göre modern toplumların temel eğilimi olan "rasyonelleşme" kavramı neyi anlatır?', 'Yaşamın hesaplanabilir, verimlilik ve kurallara dayalı biçimde örgütlenmesini', ['Dinsel inançların toplumda yeniden güçlenmesini', 'Sınıflar arasındaki farkın tamamen ortadan kalkmasını', 'Geleneklerin hukuktan daha etkili hale gelmesini'], 'Weber modernleşmeyi, geleneksel ve büyüsel düşüncenin yerini hesaplanabilirlik, verimlilik ve bürokratik kuralların almasıyla açıklar.'),
  ('Kapitalist toplumu burjuvazi ile proletarya arasındaki sınıf çatışması üzerinden açıklayan düşünür kimdir?', 'Karl Marx', ['Herbert Spencer', 'Auguste Comte', 'Talcott Parsons'], 'Marx, kapitalist toplumda üretim araçlarına sahip burjuvazi ile emeğini satarak geçinen proletarya arasında temel bir çatışma olduğunu savunmuştur.'),
  ('Marx\'ın kuramında "altyapı" kavramı neyi ifade eder?', 'Üretim güçleri ve üretim ilişkilerinden oluşan ekonomik temeli', ['Hukuk, din ve sanattan oluşan düşünsel alanı', 'Toplumun yönetim kademelerini', 'Kentlerin fiziksel planlamasını'], 'Marx\'a göre ekonomik altyapı, hukuk, siyaset, din ve ideoloji gibi üstyapı kurumlarını büyük ölçüde biçimlendirir.'),
  ('Marx\'ın kuramına göre aşağıdakilerden hangisi üstyapı kurumlarına örnek gösterilebilir?', 'Hukuk sistemi', ['Fabrika makineleri', 'Toprak mülkiyeti', 'Ücretli emek'], 'Hukuk, siyaset, din, sanat ve ideoloji Marx\'ta üstyapıyı oluşturur; makineler, mülkiyet ve emek ise altyapıya aittir.'),
  ('Marx\'a göre bir sınıfın kendi ortak çıkarlarının ve tarihsel konumunun farkına varmasına ne ad verilir?', 'Sınıf bilinci', ['Kolektif bilinç', 'Statü tutarlılığı', 'Rol kümesi'], 'Sınıf bilinci, aynı ekonomik konumdaki kişilerin ortak çıkarlarını fark ederek birlikte hareket etmeye yönelmeleridir.'),
  ('Mukaddime adlı eseriyle toplumsal olayları ilk kez sistemli biçimde inceleyen ve sosyolojinin öncülerinden sayılan İslam düşünürü kimdir?', 'İbn Haldun', ['Farabi', 'İbn Sina', 'Gazali'], '14. yüzyılda yaşayan İbn Haldun, Mukaddime\'de toplumların yapısını, değişmesini ve devletlerin yükselip çöküşünü incelemiştir.'),
  ('İbn Haldun\'un "asabiyet" kavramı en iyi hangi seçenekle açıklanır?', 'Grubu bir arada tutan dayanışma ve birlik duygusu', ['Kentli yaşamın getirdiği bolluk, lüks, konfor ve rahatlık', 'Devletin vergi toplama yetkisi', 'Bilginin kuşaktan kuşağa aktarımı'], 'Asabiyet, akrabalık ve ortak yaşamdan doğan güçlü dayanışma duygusudur; İbn Haldun\'a göre devletleri kuran güç budur.'),
  ('İbn Haldun toplumları yaşam biçimlerine göre temel olarak hangi iki türe ayırır?', 'Bedevi ve hadari', ['Mekanik ve organik', 'Cemaat ve cemiyet', 'Feodal ve kapitalist'], 'İbn Haldun göçebe ve kırsal yaşamı "bedevi", yerleşik ve kentli yaşamı "hadari" olarak adlandırır.'),
  ('Türkiye\'de sosyolojinin kurucusu sayılan ve "Türkçülüğün Esasları" adlı eseri bulunan düşünür kimdir?', 'Ziya Gökalp', ['Prens Sabahattin', 'Ahmet Rıza', 'Namık Kemal'], 'Ziya Gökalp, Durkheim\'dan etkilenmiş, İstanbul Darülfünunu\'nda ilk sosyoloji kürsüsünü yönetmiştir.'),
  ('Ziya Gökalp\'in "hars" ve "medeniyet" ayrımında "hars" neyi ifade eder?', 'Bir millete özgü değer ve duygular bütünü olan millî kültürü', ['Milletler arasında ortak olan bilim ve teknik birikimini', 'Devletin yönetim örgütünü', 'Kentlerin mimari yapısını'], 'Gökalp\'e göre hars bir millete özgü, duygu ve değerlere dayanan kültürdür; medeniyet ise milletlerarası, akla ve yönteme dayalı birikimdir.'),
  ('Araştırmacının incelediği topluluğun günlük yaşamına uzun süre katılarak bilgi topladığı tekniğe ne ad verilir?', 'Katılımlı gözlem', ['Anket', 'Belge taraması ve arşiv incelemesi', 'Deney'], 'Katılımlı gözlemde araştırmacı topluluğun bir üyesi gibi yaşamına katılır ve davranışları doğal ortamında gözlemler.'),
  ('Bir belediye, 2.000 kişiye aynı yazılı soruları yöneltip yanıtları istatistiksel olarak çözümlüyor. Kullanılan teknik hangisidir?', 'Anket', ['Monografi', 'Katılımlı gözlem', 'Yaşam öyküsü'], 'Anket, çok sayıda kişiye standart sorular sorarak sayısallaştırılabilir veri toplamayı sağlayan bir tekniktir.'),
  ('Bir köyün ya da kasabanın bütün yönleriyle ayrıntılı biçimde betimlendiği araştırmalara ne ad verilir?', 'Monografi', ['Panel araştırması', 'Pilot çalışma', 'Örneklem'], 'Monografi, tek bir toplumsal birimin (köy, kasaba, aile vb.) derinlemesine ve çok yönlü incelenmesidir.'),
  ('Araştırmacının, büyük bir evrenin özelliklerini yansıtması için seçtiği daha küçük gruba ne denir?', 'Örneklem', ['Kontrol grubu', 'Değişken', 'Hipotez'], 'Tüm evreni incelemek çoğu zaman olanaksız olduğundan, evreni temsil edecek biçimde seçilen küçük gruba örneklem denir.'),
  ('Aynı kişilerin uzun yıllar boyunca belirli aralıklarla yeniden incelendiği araştırma türü hangisidir?', 'Boylamsal araştırma', ['Kesitsel (tek zamanlı) araştırma', 'Vaka analizi', 'Deneysel araştırma'], 'Boylamsal (izleme) araştırmalarında aynı grup zaman içinde tekrar tekrar incelenir; böylece değişim izlenebilir.'),
  ('Bir araştırmacı, köy kahvesindeki sohbetlere katılmadan, kendini tanıtmadan uzaktan not alıyor. Bu teknik hangisidir?', 'Katılımsız gözlem', ['Katılımlı gözlem', 'Yarı yapılandırılmış görüşme', 'Odak grup görüşmesi'], 'Araştırmacı grubun etkinliklerine katılmadan dışarıdan izlediğinde katılımsız gözlem yapmış olur.'),
  ('Toplumu, her parçasının bütünün devamına katkı yaptığı bir sisteme benzeten kuramsal yaklaşım hangisidir?', 'Yapısal işlevselcilik', ['Çatışma kuramı', 'Sembolik etkileşimcilik', 'Fenomenoloji'], 'İşlevselcilik toplumu birbirine bağlı parçalardan oluşan bir sistem olarak görür; her kurum sistemin dengesine katkı yapar.'),
  ('Çatışma kuramının toplumsal düzeni açıklayış biçimi hangisidir?', 'Güçlü grupların kaynakları denetleyip kendi çıkarlarını sürdürmesiyle', ['Bütün grupların ortak değerlerde uzlaşmasıyla', 'Bireylerin semboller aracılığıyla anlam üretmesiyle', 'Toplumun biyolojik bir organizma gibi büyümesiyle'], 'Çatışma kuramına göre toplumsal düzen uzlaşmaya değil, egemen grupların gücüne ve kaynaklar üzerindeki denetimine dayanır.'),
  ('Merton\'a göre bir kurumun toplumun dengesini bozan, sisteme zarar veren sonuçlarına ne ad verilir?', 'İşlev bozukluğu', ['Örtük işlev', 'Kültürel yayılma', 'Rol gerilimi ve buna bağlı rol çatışması'], 'Merton, her toplumsal öğenin mutlaka olumlu işlev görmediğini, bazılarının sisteme zarar veren işlev bozukluklarına yol açabileceğini vurgular.'),
  ('Aşağıdakilerden hangisi sosyolojik anlamda "toplum" kavramını en iyi karşılar?', 'Belli bir yerde süreklilik içinde birlikte yaşayan ve ortak kültürü paylaşan insanlar', ['Bir maç için stadyumda bir araya gelmiş geçici bir kalabalık', 'Aynı gün doğmuş ama hiç karşılaşmamış kişilerden oluşan bir topluluk', 'Yalnızca aynı mesleği yapanların oluşturduğu resmi bir dernek'], 'Toplum; sürekli, örgütlü ilişkiler içinde yaşayan, ortak kültür ve kurumlara sahip insanlar bütünüdür.'),
  ('Ekonomisi fabrikalarda makineyle seri üretime, nüfusunun çoğu kentlerde ücretli çalışmaya dayanan toplum hangi türe girer?', 'Sanayi toplumu', ['Tarım toplumu', 'Çoban toplumu', 'Avcı-toplayıcı toplum'], 'Sanayi toplumunda üretim makineleşmiş, kentleşme hızlanmış ve ücretli emek yaygınlaşmıştır.'),
  ('Durkheim\'ın "organik dayanışma" kavramında toplumu bir arada tutan temel etken hangisidir?', 'İşbölümünden doğan karşılıklı bağımlılık', ['Herkesin aynı inançları ve değerleri paylaşması', 'Akrabalık bağlarının güçlü olması', 'Ortak düşmana karşı birleşme'], 'Organik dayanışmada bireyler farklı işlerde uzmanlaşır; her biri ötekinin ürettiğine muhtaç olduğundan karşılıklı bağımlılık bütünleşmeyi sağlar.'),
  ('Toplumu oluşturan statüler, roller, gruplar ve kurumlar arasındaki görece kalıcı ilişkiler ağına ne ad verilir?', 'Toplumsal yapı', ['Toplumsal hareketlilik', 'Kültürel yayılma', 'Toplumsal etkileşim'], 'Toplumsal yapı, toplumun öğeleri arasındaki düzenli ve süreklilik gösteren ilişkiler örüntüsüdür.'),
  ('Toplumsal yapının öğeleri arasında hangisi yer almaz?', 'Bir kişinin kan grubu', ['Statüler', 'Roller', 'Toplumsal kurumlar ve örgütler'], 'Statü, rol, grup ve kurum toplumsal yapının öğeleridir; kan grubu ise biyolojik bir özelliktir.'),
  ('Bir kişinin toplumsal yapı içinde bulunduğu konuma ne ad verilir?', 'Statü', ['Rol', 'Toplumsal norm', 'Değer'], 'Statü, bireyin grup ya da toplum içindeki yeridir; öğretmenlik, annelik, muhtarlık birer statüdür.'),
  ('Aşağıdakilerden hangisi doğuştan gelen (verilmiş) bir statüdür?', 'Bir ailenin kızı olmak', ['Avukat olmak', 'Belediye başkanı seçilmek', 'Kulüp kaptanı olmak'], 'Kız evlat olmak kişinin çabasıyla değil, doğuştan elde ettiği bir statüdür; diğerleri bireysel çabayla kazanılır.'),
  ('Hangisi kişinin kendi çabasıyla elde ettiği kazanılmış statüye örnektir?', 'Cerrah olmak', ['Ailenin ilk çocuğu olmak', 'Kadın olmak', 'Bir hanedanın prensi olmak'], 'Cerrahlık uzun bir eğitim ve çaba gerektirir; kardeş sırası, cinsiyet ve hanedan üyeliği ise doğuştan gelir.'),
  ('Bir kişinin sahip olduğu statüler arasında toplumda en çok onunla tanınmasını sağlayan, diğerlerinden baskın statüye ne denir?', 'Ana statü', ['Statü kümesi', 'Rol gerilimi', 'Kazanılmış rol'], 'Ana statü, kişinin toplumsal kimliğini en çok belirleyen statüdür; örneğin ünlü bir sanatçının sanatçılığı.'),
  ('Bir kişinin aynı anda sahip olduğu statülerin tümüne ne ad verilir?', 'Statü kümesi', ['Rol kümesi', 'Ana statü', 'Statü tutarsızlığı'], 'Bir kişi aynı anda anne, mühendis, vatandaş ve dernek üyesi olabilir; bunların tamamı statü kümesini oluşturur.'),
  ('Bir okulda müdür, öğretmen, hizmetli ve öğrencinin farklı konumları olması sosyolojide hangi kavramı örnekler?', 'Statüler arasındaki farklılaşma', ['Kültürel gecikme ve kurumlar arası uyumsuzluk', 'Toplumsal sapma', 'Kültürleşme'], 'Okuldaki her konum bir statüdür ve bu statüler farklı yetki, sorumluluk ve beklentiler içerir.'),
  ('Statü ile rol arasındaki ilişki en iyi hangi seçenekte ifade edilmiştir?', 'Rol, bir statüye bağlı olarak beklenen davranışlardır', ['Statü, bir rolün kişisel duygusal yönüdür', 'Rol ve statü birbirinden tamamen bağımsızdır', 'Statü, yalnız yazılı kurallarla belirlenen davranıştır'], 'Statü bir konumu, rol ise o konumdaki kişiden beklenen davranışlar bütününü anlatır; Linton\'a göre rol statünün dinamik yönüdür.'),
  ('Bir hakemin maçta kurallara uymayan oyuncuya kart göstermesi, onun hangi kavramla ilgili davranışıdır?', 'Hakemlik rolü', ['Hakemlik statüsü', 'Toplumsal kategori', 'Kültürel değer'], 'Kart göstermek hakemlik statüsündeki kişiden beklenen bir davranıştır, yani rolün bir parçasıdır.'),
  ('Hastanede nöbette olan bir doktorun, aynı akşam çocuğunun okul gösterisine katılması beklendiğinde yaşadığı durum hangisidir?', 'Rol çatışması', ['Rol gerilimi', 'Statü tutarsızlığı', 'Ana statü'], 'Rol çatışması, kişinin farklı statülerinden kaynaklanan beklentilerin birbiriyle uyuşmadığı durumdur; burada doktorluk ile ebeveynlik çatışmaktadır.'),
  ('Robert Merton\'un "rol kümesi" kavramı neyi anlatır?', 'Tek bir statüye bağlı olarak farklı kişilere karşı üstlenilen rollerin bütününü', ['Bir kişinin hayatı boyunca edindiği bütün statüleri', 'Toplumda bir rolü yapan bütün insanları', 'Rollerin birbirinden tamamen bağımsız olmasını'], 'Örneğin öğrenci statüsündeki kişinin öğretmenlerine, sınıf arkadaşlarına ve okul yönetimine karşı farklı rolleri vardır; bunların bütünü rol kümesidir.'),
  ('Aynı statüye bağlı rollerin farklı toplumlarda ve dönemlerde farklılaşabilmesi rollerin hangi özelliğini gösterir?', 'Kültürel olarak belirlenmesi ve değişebilmesi', ['Biyolojik olarak kalıtılması', 'Her toplumda ve her dönemde tıpatıp aynı kalması', 'Bireysel isteğe hiç bağlı olmaması'], 'Babalık rolünden beklenenlerin kuşaklar ya da toplumlar arasında değişmesi, rollerin kültürle biçimlendiğini gösterir.'),
  ('Toplumsal rol kavramını statü kavramıyla birlikte sistemli biçimde tanımlayan antropolog kimdir?', 'Ralph Linton', ['Bronislaw Malinowski', 'Margaret Mead', 'Franz Boas'], 'Ralph Linton, 1936 tarihli İnsanın İncelenmesi adlı eserinde statüyü bir konum, rolü ise bu konumun davranışsal yönü olarak tanımlamıştır.'),
  ('Sosyolojide "toplumsal grup" kavramını, aynı yerde rastlantıyla bulunan insanlardan ayıran özellik hangisidir?', 'Üyeler arasında sürekli etkileşim ve biz duygusu olması', ['Üyelerin aynı yaşta olması', 'Üyelerin aynı anda, aynı yerde fiziksel olarak bulunması', 'Üyelerin aynı boyda olması'], 'Toplumsal grup; ortak amaç, sürekli etkileşim, belirli kurallar ve aidiyet duygusu taşıyan insanlardan oluşur.'),
  ('Aşağıdakilerden hangisi birincil gruba örnektir?', 'Aile', ['Bir şirketin muhasebe birimi', 'Bir siyasal parti', 'Bir sendika'], 'Birincil gruplar küçük, yüz yüze, sıcak ve kalıcı ilişkilerin kurulduğu gruplardır; aile ve yakın arkadaş grubu bunların başında gelir.'),
  ('William G. Sumner\'ın "iç grup" ve "dış grup" ayrımında iç grup neyi anlatır?', 'Bireyin kendini ait hissettiği "biz" grubunu', ['Bireyin karşıt ya da yabancı gördüğü grubu', 'Bireyin hiç tanımadığı insanları', 'Resmi yasalarla kurulmuş örgütleri'], 'İç grup bireyin "biz" dediği, ait olduğu gruptur; dış grup ise "onlar" olarak algılanan gruptur.'),
  ('Georg Simmel\'e göre iki kişilik (ikili) grubun üç kişilik gruptan farkı hangisidir?', 'Üyelerden biri ayrılınca grubun sona ermesi', ['Üyeler arasında hiç etkileşim olmaması', 'Grubun her zaman daha istikrarlı ve uzun ömürlü olması', 'Üyelerin birbirini tanımaması'], 'Simmel\'e göre ikilide her üye vazgeçilmezdir; birinin ayrılması grubu bitirir. Üçlüde ise koalisyon ve arabuluculuk olanağı doğar.'),
  ('Aşağıdakilerden hangisi toplumsal kategoriye örnektir?', 'Ülkedeki 65 yaş üstü kişiler', ['Bir ailenin üyeleri', 'Bir futbol takımının oyuncuları', 'Bir sınıftaki öğrenciler'], 'Toplumsal kategori, aralarında etkileşim olmayan ama ortak bir özelliği paylaşan insanlardır; yaş grubu buna örnektir.'),
  ('Bir çarşıda sokak sanatçısını izlemek için kısa süreliğine toplanan insanlar sosyolojide hangi kavramla adlandırılır?', 'Kalabalık', ['Birincil grup', 'Toplumsal kurum', 'Resmi örgüt'], 'Kalabalık, belirli bir yerde geçici olarak bir araya gelmiş, örgütlü olmayan insan topluluğudur.'),
  ('Kitle iletişim araçlarıyla aynı yayını izleyen, ama farklı yerlerde bulunan ve birbirini tanımayan geniş insan topluluğuna ne ad verilir?', 'Kitle', ['Kalabalık', 'Birincil grup', 'Topluluk'], 'Kitle, birbirinden fiziksel olarak ayrı ama aynı uyarıcıya yönelmiş, örgütsüz ve dağınık geniş topluluktur.'),
  ('Aynı gün bir alışveriş merkezinde rastlantıyla birbirinin yanından geçen insanlar hakkında hangisi söylenebilir?', 'Bir toplumsal grup oluşturmazlar', ['Bir birincil grup oluştururlar', 'Bir resmi örgüt kurmuş olurlar', 'Bir referans grubu ya da danışma grubu oluştururlar'], 'Bu insanlar arasında ortak amaç, sürekli etkileşim ve biz duygusu olmadığından toplumsal grup sayılmazlar.'),
  ('İki ya da daha çok kişinin birbirinin davranışlarını karşılıklı olarak etkilemesine ne ad verilir?', 'Toplumsal etkileşim', ['Toplumsal kategori', 'Kültürel miras', 'Toplumsal tabakalaşma süreci'], 'Toplumsal etkileşim, bireylerin karşılıklı olarak birbirlerinin davranış, tutum ve düşüncelerini etkilemesidir.'),
  ('Bir mahallede komşuların bir araya gelip parkı birlikte temizlemesi hangi toplumsal sürece örnektir?', 'İşbirliği', ['Rekabet', 'Çatışma', 'Asimilasyon ya da eritilme'], 'İşbirliği, bireylerin ya da grupların ortak bir amaca ulaşmak için birlikte çalışmasıdır.'),
  ('Bir ailenin göç ettiği kentte toplu taşıma, alışveriş ve iş düzenine alışırken kendi kültürel kimliğini korumayı sürdürmesi hangi kavramla açıklanır?', 'Uyum', ['Asimilasyon', 'Kültürel şok', 'Toplumsal çatışma ve ayrışma'], 'Uyum, bireyin ya da grubun yeni çevrenin koşullarına ayak uydurmasıdır; kimliğin tamamen kaybedilmesi gerekmez.'),
  ('Bir şirkette iki satış ekibinin ayın en çok satış yapan ekibi olmak için kurallara uyarak yarışması hangi süreçtir?', 'Rekabet', ['Uzlaşma', 'Asimilasyon', 'Çatışma'], 'Aynı ödül için kurallar içinde yarışma rekabettir; rakibi yıpratma ya da yok etme amacı taşımaz.'),
  ('Yüz yüze olmayan, sosyal medya ya da mektup gibi araçlarla gerçekleşen etkileşime ne ad verilir?', 'Dolaylı etkileşim', ['Doğrudan etkileşim', 'Birincil etkileşim', 'Toplumsal kategori'], 'Etkileşim, tarafların aynı ortamda bulunmadığı ve bir araç aracılığıyla iletişim kurdukları durumlarda dolaylı etkileşimdir.'),
  ('Toplumun çoğunluğu tarafından iyi, doğru ve istenir kabul edilen ortak inanç ve ölçütlere ne ad verilir?', 'Toplumsal değer', ['Toplumsal norm', 'Toplumsal rol ya da görev', 'Toplumsal statü'], 'Değerler, toplumun neyin iyi ya da kötü olduğuna ilişkin ortak ölçütleridir; dürüstlük, adalet, yardımseverlik gibi.'),
  ('"Misafire saygı" değerinin günlük yaşamdaki yansımasına en uygun örnek hangisidir?', 'Gelen konuğa evin en iyi yatağının ayrılması', ['Konuğa hiç ikramda bulunmadan onu uzun süre bekletmek', 'Konuğun kapıdan geri çevrilmesi ve eve alınmaması', 'Konuğa evin yalnızca dışarısında yer gösterilmesi'], 'Konuğa en iyi olanın sunulması, misafire saygı değerinin davranışa yansımasıdır.'),
  ('Değerlerin bir toplumdan diğerine farklılık göstermesi değerlerin hangi özelliğini ortaya koyar?', 'Göreli olmalarını', ['Evrensel ve değişmez olmalarını', 'Kalıtımla geçmelerini', 'Yazılı olmalarının zorunlu olmasını'], 'Bir toplumda yüksek tutulan bir değer başka bir toplumda aynı ölçüde önemsenmeyebilir; bu durum değerlerin göreliliğini gösterir.'),
  ('Bir toplumun değerleri ile bir bireyin kişisel tercihleri arasındaki fark hangisidir?', 'Toplumsal değerlerin toplumun geneli tarafından paylaşılması', ['Kişisel tercihlerin her zaman ve her koşulda toplumsal ahlaka aykırı olması', 'Toplumsal değerlerin hiçbir zaman değişmemesi', 'Kişisel tercihlerin yazılı olarak kayıt altında olması'], 'Toplumsal değer toplumun çoğunluğunun benimsediği ortak ölçüttür; kişisel tercih ise bireyin kendi beğenisidir.'),
  ('Toplumda bireylerin nasıl davranması gerektiğini belirleyen yazılı ya da yazısız kurallara ne ad verilir?', 'Toplumsal norm', ['Toplumsal değer', 'Toplumsal statü', 'Toplumsal hareketlilik türü'], 'Normlar belirli durumlarda nasıl davranılması gerektiğini gösteren davranış kurallarıdır.'),
  ('Sosyolojide "örf" ile "âdet" arasındaki temel fark hangisidir?', 'Örfe uymamanın daha sert toplumsal tepkiyle karşılanması', ['Âdetin yazılı yasalarla korunması', 'Örfün yalnızca büyük kentlerde görülmesi ve köylerde bulunmaması', 'Âdetin ahlaki bir zorunluluk içermesi'], 'Örfler toplumca ahlaki açıdan önemli sayılan, uyulmadığında güçlü tepki gören kurallardır; âdetler ise daha hafif yaptırımı olan alışkanlıklardır.'),
  ('Belirli bir dönemde hızla yayılıp kısa sürede yerini başka beğenilere bırakan giyim tarzları hangi kavramla açıklanır?', 'Moda', ['Örf', 'Gelenek', 'Hukuk'], 'Moda, kısa süreli olarak geniş kitlelerce benimsenen ve sık değişen davranış ve beğeni kalıplarıdır.'),
  ('Bir cenazede yüksek sesle şarkı söylemenin hoş karşılanmaması, normların hangi özelliğini gösterir?', 'Duruma ve bağlama göre değişmelerini', ['Evrensel ve her yerde aynı olmalarını', 'Yalnızca yazılı olmalarını', 'Hiçbir yaptırımlarının bulunmamasını'], 'Aynı davranış bir düğünde olağan, bir cenazede ise uygunsuz sayılabilir; normlar bağlama göre belirlenir.'),
  ('Toplumun bireylerin davranışlarını normlara uygun hale getirmek için kullandığı yolların bütününe ne denir?', 'Toplumsal kontrol', ['Toplumsal hareketlilik', 'Toplumsal tabakalaşma', 'Kültürel yayılma süreci'], 'Toplumsal kontrol, toplumun düzenini korumak için bireyleri normlara uymaya yönelten ödül, ceza ve baskı mekanizmalarının bütünüdür.'),
  ('Trafik kurallarını ihlal eden bir sürücüye para cezası kesilmesi hangi tür yaptırımdır?', 'Resmi olumsuz yaptırım', ['Resmi olmayan olumlu yaptırım', 'Resmi olumlu yaptırım', 'Resmi olmayan olumsuz yaptırım'], 'Yetkili bir kurumun yasaya dayanarak uyguladığı ceza resmi ve olumsuz bir yaptırımdır.'),
  ('Bir öğrencinin başarısı nedeniyle okul tarafından takdir belgesiyle ödüllendirilmesi hangi tür yaptırıma örnektir?', 'Resmi olumlu yaptırım', ['Resmi olumsuz yaptırım', 'Resmi olmayan olumsuz yaptırım', 'Toplumsal dışlanma'], 'Kurumların belirli kurallara göre verdiği ödüller resmi olumlu yaptırımdır; yaptırım yalnız ceza değil, ödül de olabilir.'),
  ('Toplumun genel olarak kabul ettiği normlardan uzaklaşan davranışlara sosyolojide ne ad verilir?', 'Sapma', ['Uyum', 'Toplumsallaşma', 'Kültürleme'], 'Sapma, toplumun normlarına uymayan ve çoğunlukça onaylanmayan davranışları ifade eder; her sapma suç değildir.'),
  ('Edwin Sutherland\'ın "farklı ilişkiler (diferansiyel birliktelik)" kuramına göre suç davranışı nasıl ortaya çıkar?', 'Yakın ilişki kurulan kişilerden öğrenilerek', ['Doğuştan gelen kalıtsal özelliklerle', 'Yalnızca ekonomik yoksunluktan doğarak', 'Bireyin yalnız başına kalmasıyla kendiliğinden'], 'Sutherland\'a göre suç, diğer davranışlar gibi yakın gruplar içindeki etkileşim yoluyla öğrenilir.'),
  ('Bir toplumun maddi ve manevi bütün değerlerinin, yaşam biçiminin ve birikiminin toplamına ne ad verilir?', 'Kültür', ['Toplumsal yapı', 'Toplumsal kategori', 'Bireysel kişilik'], 'Kültür; dil, inanç, sanat, gelenekler, araç gereçler ve yaşam biçimi gibi toplumca üretilip aktarılan her şeyi kapsar.'),
  ('Aşağıdakilerden hangisi maddi kültür öğesidir?', 'Geleneksel bir halı', ['Bir ninni', 'Misafirperverlik anlayışı', 'Bir atasözü'], 'Maddi kültür elle tutulur, somut ürünlerden oluşur; halı bu türdendir. Ninni, atasözü ve değerler manevi kültüre girer.'),
  ('Aşağıdakilerden hangisi manevi kültürün bir öğesidir?', 'Bayramlaşma geleneği', ['Bir köprünün yapısı', 'Bakır bir cezve', 'Yöresel bir ev mimarisi'], 'Bayramlaşma geleneği bir davranış ve değer kalıbıdır; köprü, cezve ve ev mimarisi ise maddi kültürü oluşturur.'),
  ('Kültürün "öğrenilir" olması ne anlama gelir?', 'İnsanların kültürü doğuştan değil, toplum içinde edinmesi', ['Kültürün genetik olarak aktarılması', 'Kültürün yalnızca okulda ve öğretmenler aracılığıyla öğretilmesi', 'Kültürün hiçbir zaman değişmemesi'], 'Kültür kalıtımla gelmez; birey onu toplumsallaşma sürecinde aile, çevre ve kurumlar aracılığıyla öğrenir.'),
  ('Kültürün kuşaktan kuşağa aktarılmasında en temel araç hangisidir?', 'Dil', ['Mimari', 'İklim', 'Toprak'], 'Dil, deneyim ve bilgilerin sembollerle aktarılmasını sağlar; bu yüzden kültürün aktarılmasında temel araçtır.'),
  ('Bir toplumun genel kültürünü paylaşan, ama ona ek olarak kendine özgü değer, dil ve yaşam biçimi geliştiren grupların kültürüne ne ad verilir?', 'Alt kültür', ['Karşıt kültür', 'Egemen kültür', 'Kitle kültürü'], 'Alt kültür genel kültürle çatışmaz; onun içinde kendine özgü özellikler taşır. Örneğin denizcilerin ya da bir yörenin kültürü.'),
  ('Bir toplumda en geniş kesimlerin benimsediği ve kurumlarca desteklenen kültüre ne ad verilir?', 'Egemen (baskın) kültür', ['Karşıt kültür', 'Alt kültür', 'Kültürel kalıntı'], 'Egemen kültür toplumun çoğunluğunun değerlerini yansıtan, eğitim ve medya gibi kurumlarca yaygınlaştırılan kültürdür.'),
  ('Bireyin içinde doğduğu toplumun kültürünü öğrenerek benimsemesi sürecine ne ad verilir?', 'Kültürlenme', ['Kültürleşme', 'Kültürel yayılma', 'Asimilasyon'], 'Kültürlenme (enkültürasyon), bireyin kendi toplumunun kültürünü doğumdan itibaren öğrenip içselleştirmesidir.'),
  ('Farklı kültürlerin sürekli ve doğrudan temas sonucu birbirini etkileyerek değişmesine ne ad verilir?', 'Kültürleşme', ['Kültürlenme', 'Kültürel gecikme', 'Toplumsallaşma'], 'Kültürleşme (akkültürasyon), iki ya da daha çok kültürün temasıyla karşılıklı etkileşimi ve değişmesidir.'),
  ('Bir toplumda yeni bir buluşun ya da düşüncenin ilk kez ortaya çıkarak kültüre katılmasına ne ad verilir?', 'İcat', ['Kültürel yayılma', 'Kültürlenme', 'Kültürel kalıntı'], 'Yenilik ya da icat, kültüre içeriden yeni bir öğenin eklenmesidir; yayılmada ise öğe başka bir toplumdan gelir.'),
  ('Bir kişinin kendi kültürünü üstün görüp diğer kültürleri kendi kültürünün ölçütleriyle yargılamasına ne ad verilir?', 'Etnosentrizm', ['Kültürel görecelik', 'Kültürleşme', 'Kültürlenme'], 'Etnosentrizm (kültür merkezcilik), kendi kültürünü merkeze alıp başka kültürleri aşağı ya da tuhaf görme eğilimidir.'),
  ('Her kültürün kendi tarihsel ve toplumsal koşulları içinde değerlendirilmesi gerektiğini savunan yaklaşım hangisidir?', 'Kültürel görecelik', ['Etnosentrizm', 'Evrimcilik', 'Asimilasyonculuk ve eritme'], 'Kültürel görecelik, bir kültürün öğelerinin o kültürün kendi bağlamı içinde anlaşılması gerektiğini savunur.'),
  ('Bireyin içinde yaşadığı toplumun değer, norm ve davranış kalıplarını öğrenerek toplumun bir üyesi haline gelmesi sürecine ne denir?', 'Toplumsallaşma', ['Toplumsal hareketlilik sürecinin başlaması', 'Toplumsal tabakalaşmanın oluşması', 'Kültürel gecikmenin ortaya çıkması'], 'Toplumsallaşma, doğumdan ölüme kadar süren ve bireyin toplumsal bir varlık haline gelmesini sağlayan öğrenme sürecidir.'),
  ('Toplumsallaşmanın ilk ve en temel ajansı hangisidir?', 'Aile', ['Kitle iletişim araçları ve sosyal medya', 'İşyeri ve meslek örgütleri', 'Siyasal partiler ve dernekler'], 'Çocuk dil, temel değerler ve davranış kalıplarını ilk olarak ailede öğrenir; bu nedenle aile birincil toplumsallaşma ajansıdır.'),
  ('Çocukluk döneminde ailede gerçekleşen temel öğrenmeler ile ergenlik ve yetişkinlikte okul, iş ve arkadaş çevresinde süren öğrenmeler hangi ayrımla ifade edilir?', 'Birincil ve ikincil toplumsallaşma', ['Mekanik ve organik dayanışma süreçleri', 'Verilmiş ve kazanılmış statüler arasındaki fark', 'Maddi ve manevi kültürün birbirinden ayrılması'], 'Birincil toplumsallaşma erken çocuklukta ailede; ikincil toplumsallaşma ise sonraki yaşamda okul, iş ve diğer gruplar aracılığıyla gerçekleşir.'),
  ('Cooley\'in ayna benlik kavramına göre bireyin kendilik algısı nasıl oluşur?', 'Başkalarının kendisi hakkındaki düşüncelerini nasıl algıladığına göre', ['Kalıtımla gelen yeteneklerin kendiliğinden ortaya çıkmasıyla, başkalarından etkilenmeden', 'Yalnızca bireyin kendi iç gözlemiyle', 'Toplumsal yapıdan tamamen bağımsız biçimde'], 'Ayna benlikte birey, başkalarına nasıl göründüğünü hayal eder, onların yargısını yorumlar ve buna göre kendine dair bir duygu geliştirir.'),
  ('Sosyolojide "toplumsal kimlik" kavramı neyi anlatır?', 'Bireyin üyesi olduğu gruplara ve kategorilere dayalı benlik tanımını', ['Bireyin parmak izi gibi biyolojik özelliklerini', 'Bireyin yalnızca kimlik kartında yazan bilgilerini', 'Bireyin kişisel zevklerini'], 'Toplumsal kimlik, bireyin kendini bir ulus, meslek, aile ya da topluluk gibi gruplara aidiyetiyle tanımlamasıdır.'),
  ('Bir toplumda bireylerin ve grupların gelir, saygınlık ve güç gibi değerler bakımından hiyerarşik olarak sıralanmasına ne ad verilir?', 'Toplumsal tabakalaşma', ['Toplumsal etkileşim ve işbirliği', 'Kültürel yayılma ve kültürleşme', 'Toplumsallaşma ve kişilik gelişimi'], 'Tabakalaşma, toplumdaki eşitsizliklerin süreklilik gösteren hiyerarşik bir düzen içinde yapılaşmasıdır.'),
  ('Doğuştan belirlenen, tabakalar arası geçişin dinsel kurallarla neredeyse tamamen kapalı olduğu tabakalaşma sistemi hangisidir?', 'Kast', ['Sınıf sistemi ve meslek grupları', 'Açık tabakalaşma düzeni', 'Liyakate dayalı sistem'], 'Kast sisteminde birey doğduğu kastta kalır; evlilik ve meslek kast içinde belirlenir. Geleneksel Hindistan en bilinen örneğidir.'),
  ('Avrupa\'da Orta Çağ\'da görülen, soylular, din adamları ve köylüler gibi hukuken tanımlanmış tabakalardan oluşan sisteme ne ad verilir?', 'Zümre', ['Kast düzeni ve dinsel kurallar', 'Modern sınıf sistemi', 'Sınıfsız toplum düzeni'], 'Zümre sisteminde tabakalar hukukla belirlenmiş hak ve ödevlere sahiptir; geçiş kasta göre biraz daha mümkündür ama sınırlıdır.'),
  ('Pierre Bourdieu\'nün eğitim, beğeni ve kültürel birikimden oluşan, toplumsal konumu etkileyen sermaye türü hangisidir?', 'Kültürel sermaye', ['Ekonomik sermaye ve mülkiyet', 'Toplumsal sermaye ve ilişki ağları', 'Simgesel şiddet ve tahakküm'], 'Bourdieu\'ye göre kültürel sermaye; eğitim nitelikleri, dil kullanımı ve beğeniler gibi, ailede edinilip toplumsal konumu yeniden üreten birikimdir.'),
  ('Bir kişinin tanıdıkları ve ilişki ağları sayesinde iyi bir işe girmesi Bourdieu\'nün hangi kavramıyla açıklanır?', 'Toplumsal sermaye', ['Kültürel sermaye ve eğitim nitelikleri', 'Ekonomik sermaye ve maddi varlıklar', 'Habitus ve bedenselleşmiş eğilimler'], 'Toplumsal sermaye, bireyin dahil olduğu ilişki ağlarından ve bunların sağladığı kaynaklardan oluşur.'),
  ('Bireylerin ya da grupların toplumsal konumlarının değişmesine ne ad verilir?', 'Toplumsal hareketlilik', ['Kültürel yayılma ve kültürleşme', 'Toplumsal kontrol ve yaptırım', 'Toplumsal etkileşim süreçleri'], 'Toplumsal hareketlilik, bireyin ya da grubun bir statüden diğerine, bir tabakadan başka bir tabakaya geçişidir.'),
  ('Bir işçinin eğitim alarak mühendis olması hangi tür hareketliliktir?', 'Dikey yukarı doğru hareketlilik', ['Yatay hareketlilik ve meslek değişimi', 'Dikey aşağı doğru hareketlilik', 'Coğrafi hareketlilik ve göç'], 'Toplumsal hiyerarşide daha üst bir konuma geçiş dikey ve yukarı doğru hareketliliktir.'),
  ('Bir lise öğretmeninin aynı statü düzeyindeki başka bir okulda öğretmenliğe başlaması hangi hareketlilik türüdür?', 'Yatay hareketlilik', ['Dikey yukarı doğru hareketlilik', 'Kuşaklar arası hareketlilik', 'Dikey aşağı doğru hareketlilik'], 'Toplumsal konumu değişmeden yalnızca yer ya da kurum değiştirmek yatay hareketliliktir.'),
  ('Babası çiftçi olan bir kişinin profesör olması, iki kuşak karşılaştırıldığında hangi hareketlilik türüne örnektir?', 'Kuşaklar arası hareketlilik', ['Kuşak içi hareketlilik', 'Yatay hareketlilik', 'Coğrafi hareketlilik ve göç'], 'Ebeveyn ile çocuğun toplumsal konumlarının karşılaştırılması kuşaklar arası hareketliliği gösterir.'),
  ('Bir kişinin yaşamı boyunca stajyerlikten başlayıp genel müdürlüğe yükselmesi hangi tür hareketlilik olarak adlandırılır?', 'Kuşak içi hareketlilik', ['Kuşaklar arası hareketlilik', 'Yatay hareketlilik', 'Coğrafi hareketlilik'], 'Bir bireyin kendi yaşam süresi içindeki konum değişimi kuşak içi (yaşam içi) hareketliliktir.'),
  ('Toplumsal yapıda, kurumlarda, değer ve normlarda zaman içinde meydana gelen farklılaşmaya ne ad verilir?', 'Toplumsal değişme', ['Toplumsal kategori ve gruplaşma', 'Rol çatışması ve rol gerilimi', 'Kültürel evrenseller ve ortak öğeler'], 'Toplumsal değişme, toplumun yapısında ve işleyişinde zaman içinde oluşan dönüşümlerdir.'),
  ('Matbaanın icadıyla bilginin geniş kitlelere yayılması ve okuryazarlığın artması toplumsal değişmenin hangi etkenine örnektir?', 'Teknolojik etken', ['Coğrafi ve iklimsel etken', 'Demografik etken ve nüfus artışı', 'Biyolojik etken ve kalıtım'], 'Matbaa gibi teknolojik yenilikler iletişimi, eğitimi ve düşünce dünyasını dönüştürerek toplumsal değişmeye yol açar.'),
  ('Kent nüfusunun toplam nüfus içindeki payının artması ve kentli yaşam biçiminin yaygınlaşması sürecine ne ad verilir?', 'Kentleşme', ['Kültürlenme', 'Asimilasyon', 'Tabakalaşma'], 'Kentleşme, nüfusun kırdan kente yığılmasıyla birlikte kent sayısının ve kentli nüfusun artması, kentsel yaşam biçiminin yayılmasıdır.'),
  ('Bir kişinin daha iyi iş olanakları için Türkiye\'den Almanya\'ya yerleşmesi hangi göç türüne örnektir?', 'Dış göç', ['İç göç', 'Mevsimlik göç', 'Zorunlu göç'], 'Bir ülkenin sınırları dışına yapılan göç dış göçtür; ülke içindeki yer değiştirme ise iç göçtür.'),
  ('Fındık toplama döneminde Karadeniz\'e gidip iş bitince yaşadığı yere dönen tarım işçilerinin hareketi hangi göç türüdür?', 'Mevsimlik göç', ['Kalıcı dış göç', 'Beyin göçü', 'Zorunlu göç'], 'Belirli dönemlerde iş için yapılan ve sonra geri dönülen geçici yer değiştirme mevsimlik göçtür.'),
  ('Sosyolojide geleneksel toplumdan sanayileşmiş, kentleşmiş ve rasyonel örgütlenmeye dayalı topluma geçiş sürecine ne ad verilir?', 'Modernleşme', ['Kültürlenme', 'Asimilasyon', 'Kırsallaşma'], 'Modernleşme; sanayileşme, kentleşme, bilimsel düşünce, eğitimin yaygınlaşması ve bürokratik örgütlenmeyi kapsayan çok yönlü bir dönüşümdür.'),
  ('Dünya ölçeğinde ekonomik, kültürel ve siyasal ilişkilerin yoğunlaşarak toplumların birbirine daha bağımlı hale gelmesine ne denir?', 'Küreselleşme', ['Yerelleşme ve içe kapanma', 'Kültürel gecikme', 'Kırsal kalkınma'], 'Küreselleşme, ticaret, iletişim ve ulaşım ağlarının dünyayı birbirine bağlamasıyla toplumlar arasındaki karşılıklı bağımlılığın artmasıdır.'),
  ('Toplumun temel ihtiyaçlarını karşılamak için oluşmuş, görece kalıcı ve düzenli davranış, norm ve rol örüntülerine ne ad verilir?', 'Toplumsal kurum', ['Toplumsal kategori', 'Geçici kalabalık', 'Moda akımı'], 'Aile, eğitim, din, ekonomi ve siyaset gibi kurumlar toplumun süreklilik gösteren temel ihtiyaçlarına yanıt veren yapılardır.'),
  ('Aşağıdakilerden hangisi bir toplumsal kurum değil, bir örgüt örneğidir?', 'Belirli bir üniversite', ['Eğitim kurumu', 'Aile', 'Din'], 'Eğitim, aile ve din toplumsal kurumlardır; belirli bir üniversite ise eğitim kurumunun içinde yer alan somut bir örgüttür.'),
  ('Her toplumda bulunan temel toplumsal kurumlar sosyoloji ders kitaplarında genellikle hangi beşli ile anılır?', 'Aile, eğitim, din, ekonomi, siyaset', ['Moda, kalabalık, kitle, dedikodu, eğlence', 'Kent, köy, kasaba, mahalle, sokak', 'Gelenek, örf, âdet, görenek, moda'], 'Aile, eğitim, din, ekonomi ve siyaset toplumların ortak temel ihtiyaçlarına yanıt veren beş temel kurum olarak kabul edilir.'),
  ('Anne, baba ve evlenmemiş çocuklardan oluşan aile tipine ne ad verilir?', 'Çekirdek aile', ['Geniş aile ve yaşlı akrabalar', 'Parçalanmış aile ve tek ebeveyn', 'Ataerkil geniş aile yapısı'], 'Çekirdek aile, eşler ve evlenmemiş çocuklarından oluşan küçük aile birimidir; sanayi toplumlarında yaygındır.'),
  ('Büyükanne, büyükbaba, evli çocuklar ve torunların aynı çatı altında yaşadığı aile tipi hangisidir?', 'Geniş aile', ['Çekirdek aile ve çocuklar', 'Tek ebeveynli aile', 'Çocuksuz eşlerden oluşan aile'], 'Geniş aile, birden fazla kuşağın ve evli çocukların bir arada yaşadığı ailedir; tarım toplumlarında daha yaygındır.'),
  ('Ailenin toplum açısından en temel işlevlerinden biri olan "biyolojik işlev" neyi ifade eder?', 'Neslin devamını sağlamayı', ['Devletin vergilerini toplamayı ve harcamayı', 'Ülkenin dış ilişkilerini yürütmeyi', 'Kentlerin altyapısını kurmayı'], 'Aile, çocuk sahibi olma yoluyla toplumun biyolojik sürekliliğini sağlar.'),
  ('Çocuğa ilk kez dil, temel değerler ve görgü kurallarının öğretilmesi ailenin hangi işlevine örnektir?', 'Toplumsallaştırma işlevi', ['Ekonomik işlev ve üretim', 'Koruyucu işlev ve barınma', 'Siyasal işlev ve yönetim'], 'Aile çocuğun ilk toplumsallaşma ortamıdır; değerler ve kurallar ilk olarak ailede kazanılır.'),
  ('Bir ailede eşlerin kararları birlikte aldığı, ev işlerini ve sorumlulukları paylaştığı aile tipine ne ad verilir?', 'Eşitlikçi (demokratik) aile', ['Ataerkil aile ve baba otoritesi', 'Anaerkil aile ve anne otoritesi', 'Geniş aile ve büyükbaba otoritesi'], 'Eşitlikçi ailede otorite ve sorumluluklar eşler arasında paylaşılır.'),
  ('Bir kişinin aynı anda yalnızca bir eşle evli olduğu evlilik biçimine ne ad verilir?', 'Monogami', ['Poligami', 'Endogami', 'Egzogami'], 'Monogami tek eşli evliliktir; Türkiye dahil birçok ülkede yasal olarak tanınan tek evlilik biçimidir.'),
  ('Bir kişinin aynı anda birden fazla eşle evli olduğu evlilik biçiminin genel adı nedir?', 'Poligami', ['Monogami', 'Endogami', 'Egzogami'], 'Poligami çok eşliliktir; bir erkeğin birden çok eşi olması poligini, bir kadının birden çok eşi olması poliandridir.'),
  ('Bir kadının aynı anda birden fazla erkekle evli olduğu ve çok az toplumda görülen evlilik biçimine ne ad verilir?', 'Poliandri', ['Poligini', 'Monogami', 'Endogami'], 'Poliandri, kadının birden fazla kocası olmasıdır; Tibet\'in bazı bölgeleri gibi sınırlı topluluklarda görülmüştür.'),
  ('Kan bağına dayanan akrabalık ile evlilik yoluyla kurulan akrabalık sosyolojide hangi adlarla ayrılır?', 'Kan akrabalığı ve hısımlık', ['Ataerkil ve anaerkil aile türleri arasındaki fark', 'Endogami ve egzogami kuralları ile ilgili ayrım', 'Çekirdek ve geniş aile tipleri arasındaki ayrım'], 'Anne, baba ve kardeşler kan akrabasıdır; kayınvalide, kayınbirader gibi evlilikle kurulan bağlar ise hısımlıktır.'),
  ('Bir kadının eşinin annesi ile arasındaki akrabalık hangi türdendir?', 'Hısımlık', ['Kan akrabalığı ve soy bağı', 'Süt kardeşliği ve emzirme bağı', 'Manevi akrabalık ve kirvelik'], 'Kayınvalide ile gelin arasındaki bağ evlilik yoluyla kurulduğundan hısımlıktır.'),
  ('Soyun ve mirasın yalnızca baba tarafından izlendiği akrabalık sistemine ne ad verilir?', 'Babasoylu (patrilineal) sistem', ['Anasoylu (matrilineal) sistem', 'Çift taraflı (bilateral) sistem', 'Anayerli (matrilokal) sistem'], 'Babasoylu sistemde soy, aile adı ve miras baba üzerinden aktarılır.'),
  ('Evlenen çiftin erkeğin ailesinin yanına yerleşmesi kuralı hangi kavramla anılır?', 'Babayerlilik (patrilokal yerleşim)', ['Anayerlilik (matrilokal yerleşim)', 'Yeni yerlilik (neolokal yerleşim)', 'Dış evlilik (egzogami)'], 'Babayerli yerleşimde gelin, kocasının ailesinin evine ya da yakınına yerleşir; geleneksel Türk köylerinde yaygındır.'),
  ('Sanayi toplumlarında yeni evlenen çiftlerin her iki ailenin de evinden ayrı, kendi evlerini kurması hangi yerleşim kuralıdır?', 'Yeni yerlilik (neolokal yerleşim)', ['Babayerlilik (patrilokal yerleşim)', 'Anayerlilik (matrilokal yerleşim)', 'Babasoyluluk ve miras kuralı'], 'Neolokal yerleşimde çift ayrı bir hane kurar; bu çekirdek ailenin yaygınlaşmasıyla ilişkilidir.'),
  ('Bir toplumun bilgi, beceri ve değerlerini planlı ve sistemli biçimde yeni kuşaklara aktaran toplumsal kurum hangisidir?', 'Eğitim', ['Ekonomi', 'Siyaset', 'Moda'], 'Eğitim kurumu, okul gibi örgütler aracılığıyla bilgi ve değerlerin bilinçli ve planlı biçimde aktarılmasını sağlar.'),
  ('Türkiye\'de 1924 yılında çıkarılan ve bütün eğitim kurumlarını Maarif Vekâletine (bugünkü Milli Eğitim Bakanlığı) bağlayan yasa, eğitim kurumunun hangi işlevini güçlendirmeyi amaçlamıştır?', 'Ulusal bütünleşmeyi sağlama işlevini', ['Ekonomik üretim işlevini', 'Biyolojik işlevi', 'Bireylerin dinsel tören yönetme işlevini'], 'Tevhid-i Tedrisat Kanunu eğitimi tek çatı altında birleştirerek ortak bir kültür ve ulusal bütünleşme sağlamayı amaçlamıştır.'),
  ('Sosyoloji dini incelerken öncelikle hangi soruya yanıt arar?', 'Dinin toplumsal yaşamdaki işlevleri ve etkileri nelerdir?', ['Hangi dinin inançları doğrudur ve hangisi yanlıştır?', 'Evrenin fiziksel yasaları nelerdir ve nasıl işler?', 'Bireyin rüyaları neyi anlatır ve nasıl yorumlanır?'], 'Din sosyolojisi inançların doğruluğunu değil, dinin toplumsal ilişkiler, kurumlar ve davranışlar üzerindeki etkisini inceler.'),
  ('Durkheim dinsel yaşamı açıklarken her şeyi hangi iki alana ayırır?', 'Kutsal ve dünyevi (profan)', ['Altyapı ve üstyapı', 'Ön sahne ve kulis (dramaturji)', 'Cemaat ve cemiyet'], 'Durkheim\'a göre din, kutsal sayılan şeylerle ilgili inanç ve uygulamaların topluluğu bir arada tutan sistemidir; kutsal, gündelik (profan) olandan ayrılır.'),
  ('Bayram namazı sonrası cemaatin toplu halde bayramlaşması ve küslerin barışması, dinin hangi toplumsal işlevine örnektir?', 'Toplumsal bütünleşmeyi güçlendirme', ['Ekonomik üretimi artırma ve verimi yükseltme', 'Siyasal otoriteyi devirme ve değiştirme', 'Meslek eğitimi verme ve beceri kazandırma'], 'Ortak ibadet ve törenler topluluk üyelerini bir araya getirerek dayanışma ve bütünleşmeyi pekiştirir.'),
  ('Marx\'ın dine ilişkin "halkın afyonu" benzetmesi dinin hangi işlevine dikkat çeker?', 'Ezilenlerin acılarını hafifletip mevcut düzeni sorgulamalarını engellemesine', ['Bilimsel buluşları hızlandırmasına ve teknolojiyi geliştirmesine', 'Ekonomik eşitsizliği tamamen ortadan kaldırmasına', 'Toplumsal hareketliliği artırmasına'], 'Marx dinin, insanların dünyadaki sıkıntılarına öte dünyada teselli sunarak toplumsal eşitsizliği kabullenmelerine yol açtığını savunur.'),
  ('Toplumda farklı işlerin farklı kişi ve gruplar arasında paylaştırılmasına ne ad verilir?', 'İşbölümü', ['Toplumsal hareketlilik', 'Toplumsal kontrol', 'Kültürel yayılma'], 'İşbölümü, üretim ve diğer etkinliklerin farklı görevlere ayrılarak bireyler ve gruplar arasında paylaştırılmasıdır.'),
  ('Üretim araçlarının özel mülkiyette olduğu ve üretimin piyasada kâr amacıyla yapıldığı ekonomik sisteme ne ad verilir?', 'Kapitalizm', ['Feodalizm', 'Merkantilizm', 'Kooperatifçilik'], 'Kapitalizmde üretim araçları özel kişilere aittir; mal ve hizmetler piyasada kâr elde etmek için üretilir.'),
  ('Ekonomide hizmet sektörüne hangisi örnek gösterilebilir?', 'Bankacılık', ['Buğday tarımı', 'Demir madenciliği', 'Otomobil üretimi'], 'Bankacılık, eğitim, sağlık ve turizm hizmet sektörüne; tarım ve madencilik birincil, imalat ise ikincil sektöre girer.'),
  ('Weber\'e göre "iktidar" (güç) kavramı neyi ifade eder?', 'Bir kişinin direnişe rağmen kendi iradesini başkalarına kabul ettirebilme olasılığını', ['Toplumun ortak değerlerini paylaşan bireylerin aynı yerde bulunmasını', 'Bir kişinin doğuştan sahip olduğu toplumsal konumu', 'Bir grubun kültürünü başka bir gruba aktarmasını'], 'Weber iktidarı, toplumsal ilişki içinde bir aktörün direnişe karşın kendi isteğini gerçekleştirebilme şansı olarak tanımlar.'),
  ('Siyaset kurumunun toplum açısından temel işlevi en iyi hangi seçenekte ifade edilmiştir?', 'Toplumsal düzeni sağlamak ve kolektif kararlar almak', ['Neslin biyolojik devamını sağlamak', 'Bireylere ilk dil eğitimini vermek', 'Mal ve hizmet üretimini doğrudan yapmak ve fiyatları belirlemek'], 'Siyaset kurumu, toplumun ortak sorunlarına ilişkin bağlayıcı kararların alınmasını ve düzenin korunmasını sağlar.'),
  ('Weber\'e göre bürokratik örgütlenmenin belirgin özelliklerinden biri hangisidir?', 'Yazılı kurallar ve hiyerarşik makamlar', ['Kişisel ilişkilere dayalı esnek kararlar', 'Görevlerin soy bağına göre dağıtılması', 'Kuralların sözlü ve değişken olması'], 'Weber\'in ideal tip bürokrasisinde yazılı kurallar, belirgin görev tanımları, makam hiyerarşisi ve liyakate dayalı atama bulunur.'),
  ('Bir örgütte işe alma ve terfinin akrabalık ya da tanıdıklık yerine bilgi, beceri ve sınav başarısına göre yapılması hangi ilkeyle ifade edilir?', 'Liyakat', ['Nepotizm', 'Kayırmacılık', 'Karizma'], 'Liyakat, görevlerin yetenek ve yeterliğe göre verilmesidir; nepotizm ise akraba kayırmacılığıdır.'),
  ('Gazete, radyo, televizyon ve internet gibi, bir kaynaktan çok sayıda kişiye aynı anda ileti ulaştıran araçların genel adı nedir?', 'Kitle iletişim araçları', ['Birincil gruplar ve aile içi ilişkiler', 'Toplumsal kategoriler ve yaş grupları', 'Geleneksel kurumlar ve köy odaları'], 'Kitle iletişim araçları, iletileri geniş ve dağınık kitlelere hızla ulaştıran teknolojik araçlardır.'),
  ('Nüfusun büyüklüğünü, yapısını, dağılımını ve değişimini inceleyen bilim dalı hangisidir?', 'Demografi', ['Etnografya', 'Kriminoloji', 'Hermenötik'], 'Demografi; doğum, ölüm ve göç gibi olaylara bağlı olarak nüfusun değişimini istatistiksel yöntemlerle inceler.'),
  ('Demografik dönüşüm kuramına göre sanayileşmenin başlangıç evresinde nüfus artışının hızlanmasının nedeni hangisidir?', 'Ölüm oranlarının düşmesi, doğum oranlarının ise bir süre yüksek kalması', ['Doğum oranlarının birden sıfıra inmesi', 'Ölüm oranlarının hızla yükselmesi', 'Kentlerden köylere yoğun göç yaşanması'], 'Sağlık ve beslenmedeki iyileşmelerle ölümler azalır, doğum oranları ise daha geç düştüğü için aradaki fark nüfusu hızla artırır.'),
  ('Sosyolojide bir durumun "toplumsal sorun" sayılabilmesi için en temel koşul hangisidir?', 'Toplumun önemli bir kesimini etkilemesi ve çözüm gerektirdiğinin kabul edilmesi', ['Yalnızca tek bir bireyin kişisel yaşamını etkilemesi', 'Doğal bir afet olarak ortaya çıkması ve kısa sürmesi', 'Yasalarda açıkça tanımlanmış olması'], 'Toplumsal sorun, toplumun geniş bir kesimini olumsuz etkileyen ve toplumca değiştirilmesi gerektiği düşünülen durumdur.'),
  ('Bir kişinin temel yaşam ihtiyaçlarını karşılayamayacak düzeyde gelire sahip olması hangi kavramla adlandırılır?', 'Mutlak yoksulluk', ['Göreli yoksulluk', 'Statü tutarsızlığı', 'Yapısal hareketlilik'], 'Mutlak yoksulluk, beslenme, barınma ve giyinme gibi en temel ihtiyaçların karşılanamamasıdır.'),
  ('Engelli bireylerin kamusal binalara erişimini kolaylaştıran rampaların yapılması sosyolojik açıdan hangi amaca hizmet eder?', 'Toplumsal katılımın ve bütünleşmenin artırılmasına', ['Toplumsal tabakalaşmanın güçlendirilmesine', 'Kültürel gecikmenin derinleşmesine', 'Toplumsal dışlanmanın artırılmasına ve ayrışmanın derinleşmesine'], 'Fiziksel engellerin kaldırılması dezavantajlı grupların toplumsal yaşama tam katılımını destekler.'),
  ('Toplumsal olayları zaman ve yer belirterek, tek ve biricik olaylar olarak inceleyen bilim dalı hangisidir?', 'Tarih', ['Sosyoloji', 'Demografi', 'Ekonomi'], 'Tarih belirli olayları geçmişteki bağlamıyla inceler; sosyoloji ise toplumsal olaylardaki genel düzenlilikleri arar.'),
  ('Sosyal psikolojinin ilgi alanı en iyi hangi seçenekte belirtilmiştir?', 'Bireyin düşünce ve davranışlarının başkalarının varlığından nasıl etkilendiği', ['Gezegenlerin hareketlerinin toplumsal takvimlere etkisi', 'Bir toplumun yalnızca nüfus sayımı sonuçları', 'Bir dilin ses yapısının tarihsel gelişimi'], 'Sosyal psikoloji, bireyle toplum arasındaki etkileşimi, özellikle grup içinde bireyin tutum ve davranışlarını inceler.'),
  ('Chicago Okulu\'ndan Ernest Burgess\'in kentin merkezden dışa doğru halkalar biçiminde büyüdüğünü öne süren modeli hangi adla bilinir?', 'Eşmerkezli halkalar modeli', ['Dünya sistemleri modeli', 'AGIL şeması ve işlevsel model', 'Üç hal yasası'], 'Burgess\'in modeline göre kent iş merkezinden başlayarak geçiş bölgesi, işçi konutları ve banliyöler gibi eşmerkezli halkalar halinde genişler.'),
  ('Osmanlı toplumunda yönetenler ile yönetilenleri ayırmak için kullanılan iki temel kategori hangileridir?', 'Askeri ve reaya', ['Burjuva ve proletarya', 'Bedevi ve hadari', 'Cemaat ve cemiyet'], 'Osmanlı\'da devlet görevlileri, ordu mensupları ve ulema askeri sınıfı; vergi veren köylü, esnaf ve tüccarlar ise reayayı oluşturuyordu.'),
  ('Osmanlı toplumunda cami, medrese, çeşme, imaret ve kervansaray gibi hizmetlerin önemli bölümünü sağlayan kurum hangisidir?', 'Vakıf', ['Lonca', 'Tımar', 'Divan-ı Hümayun'], 'Vakıflar, bir mülkün gelirinin kalıcı olarak toplumsal hizmetlere ayrılmasıyla kurulur ve eğitim, sağlık, sosyal yardım gibi alanlarda işlev görürdü.'),
  ('Bir araştırmada etkisi incelenen ve araştırmacının neden olarak düşündüğü değişkene ne ad verilir?', 'Bağımsız değişken', ['Bağımlı (sonuç) değişken', 'Sabit değişken', 'Kontrol grubu'], 'Bağımsız değişken neden olarak ele alınan, bağımlı değişken ise ondan etkilendiği düşünülen sonuçtur.'),
  ('Bir toplumu, bir topluluğu ya da bir kurumu tek bir örnek olarak derinlemesine inceleyen yönteme ne ad verilir?', 'Vaka (örnek olay) çalışması', ['Kesitsel istatistik taraması', 'Deneysel kontrol grubu çalışması', 'Ulusal nüfus sayımı'], 'Vaka çalışması tek bir birimi birçok veri kaynağı kullanarak ayrıntılı biçimde inceler.'),
  ('Sosyolojide "toplumsal cinsiyet" kavramını "biyolojik cinsiyet"ten ayıran özellik hangisidir?', 'Toplumun kadınlık ve erkeklikle ilgili kültürel beklentilerini anlatması', ['Kişinin doğuştan gelen bedensel özelliklerini anlatması', 'Yalnızca hukuki kimlik belgelerini anlatması', 'Her toplumda tamamen aynı olması'], 'Biyolojik cinsiyet bedensel özelliklere; toplumsal cinsiyet ise toplumun kadın ve erkeğe yüklediği rol, davranış ve beklentilere işaret eder.'),
  ('Sosyolojinin kendi bulgularını genelleştirmeye çalışması ne anlama gelir?', 'Tek tek olaylardan yola çıkarak benzer durumlar için geçerli düzenlilikler aramak', ['Her olayı yalnızca kendine özgü bir olay olarak görmek', 'Bulguları hiç kimseyle paylaşmamak', 'Yalnızca bir kişinin deneyimini incelemek'], 'Sosyoloji tek bir olayı değil, benzer olayların ortak özelliklerini ve tekrar eden örüntülerini ortaya koymaya çalışır.'),
  ('Boşanma ya da eşlerden birinin ölümü sonucu çocuklarıyla birlikte yaşayan tek bir ebeveynden oluşan aile tipine ne ad verilir?', 'Tek ebeveynli aile', ['Geniş aile ve büyükanne-büyükbaba', 'Ataerkil çekirdek aile', 'Çok kuşaklı köy ailesi'], 'Tek ebeveynli aile, anne ya da babadan yalnızca birinin çocuklarla birlikte yaşadığı aile biçimidir.'),
  ('Ailenin "ekonomik işlevi" en iyi hangi seçenekte örneklenmiştir?', 'Hane üyelerinin gelirlerini ortak harcamalarda birleştirmesi', ['Çocuklara bayram geleneklerinin öğretilmesi', 'Ailenin dinsel törenlere katılması', 'Çocukların ilk kez okula kaydedilmesi'], 'Ailenin ekonomik işlevi; üretim, gelir sağlama, tüketim ve mülkün aktarılması gibi etkinlikleri kapsar.'),
  ('Aynı apartmanda oturan ve her ay toplantı yapıp ortak giderlere karar veren kat malikleri sosyolojik açıdan neyi oluşturur?', 'Belirli bir amaca yönelik ikincil bir grup', ['Birincil grup ve aile benzeri bir yapı', 'Toplumsal kategori ve istatistiksel bir toplam', 'Geçici bir kalabalık ve rastlantısal topluluk'], 'Kat malikleri belirli bir amaç (bina yönetimi) çevresinde, kurallara göre ilişki kuran ikincil bir grup oluşturur.'),
  ('Bir grupta üyelerin birbirine bağlılık ve grupta kalma isteğinin gücünü ifade eden kavram hangisidir?', 'Grup uyumu', ['Toplumsal kategori ve sınıflama', 'Toplumsal hareketlilik ve geçiş', 'Kültürel gecikme ve uyumsuzluk'], 'Grup uyumu, üyelerin gruba bağlılığı ve birbirlerine duydukları yakınlıkla ilgilidir; yüksek uyum grubu daha dayanıklı kılar.'),
  ('Bir toplumda kızlara oyuncak bebek, erkeklere oyuncak araba alınması gibi uygulamalar hangi süreçle ilişkilidir?', 'Toplumsal cinsiyet rollerinin öğrenilmesi', ['Kültürel yayılma ve uluslararası göç süreçleri', 'Toplumsal hareketlilik ve meslek değişimi', 'Sapma davranışının ortaya çıkışı'], 'Çocuklara cinsiyete göre farklı oyuncaklar verilmesi, toplumsal cinsiyet rollerinin toplumsallaşma yoluyla öğretilmesine örnektir.'),
  ('Bir ülkede iç savaş nedeniyle halkın komşu ülkelere kaçmak zorunda kalması hangi tür göçtür?', 'Zorunlu göç', ['Gönüllü ekonomik göç', 'Mevsimlik tarım göçü', 'Beyin göçü'], 'Savaş, afet ya da baskı gibi nedenlerle insanların yaşadıkları yeri istemeden terk etmesi zorunlu göçtür.'),
  ('Marx\'a göre kapitalist toplumda sınıf konumunu belirleyen temel ölçüt hangisidir?', 'Üretim araçlarıyla ilişki', ['Kişinin eğitim düzeyi ve diplomaları', 'Kişinin dinsel inancı ve mezhebi', 'Kişinin doğduğu bölge ve kenti'], 'Marx için sınıf, üretim araçlarına sahip olup olmamaya göre belirlenir: sahip olanlar burjuvazi, emeğini satanlar proletaryadır.'),
  ('Bir toplumda kadınların aynı işi yapan erkeklere göre daha düşük ücret alması hangi tabakalaşma boyutuyla ilgilidir?', 'Toplumsal cinsiyete dayalı eşitsizlik', ['Kast sistemine dayalı ayrım', 'Yaşa ve kıdeme dayalı yatay hareketlilik', 'Coğrafi bölgeye dayalı iç göç'], 'Toplumsal cinsiyet, gelir ve olanakların dağılımında belirleyici olabilen bir tabakalaşma boyutudur.'),
  ('Bir ekonomide toprağın, madenlerin ve ormanların doğrudan işlendiği sektör hangisidir?', 'Birincil sektör', ['İkincil sektör', 'Üçüncül (hizmet) sektör', 'Bilgi sektörü'], 'Tarım, hayvancılık, balıkçılık, ormancılık ve madencilik birincil sektörü oluşturur.'),
  ('Bir dinin belirli bir toplumda resmi ve örgütlü yapısıyla (din adamları, ibadethaneler ve kurallar) ele alınması sosyolojide hangi kavramla anlatılır?', 'Dinin kurumsal boyutu', ['Dinin bireysel deneyim boyutu', 'Dinin biyolojik temeli', 'Dinin coğrafi dağılımı'], 'Dinin kurumsal boyutu; roller, örgütler, ritüeller ve kurallardan oluşan toplumsal örgütlenmesini ifade eder.'),
  ('Teknolojinin bir toplumsal değişme etkeni olarak ele alınmasına en uygun örnek hangisidir?', 'İnternetin uzaktan çalışmayı yaygınlaştırması', ['Bir dağın yüksekliğinin ölçülmesi', 'Bir bitkinin sulanma sıklığı', 'Bir şiirin hece ölçüsü'], 'İnternet gibi teknolojiler çalışma biçimlerini, aile içi zaman kullanımını ve kentleşmeyi etkileyerek toplumsal yaşamı dönüştürür.'),
  ('Bir ülkede belirli bir tarihte bütün nüfusun yaş, cinsiyet, eğitim gibi özellikleriyle sayılmasına ne ad verilir?', 'Nüfus sayımı', ['Örneklem anketi', 'Monografi', 'Odak grup çalışması'], 'Nüfus sayımı, bir ülkedeki bütün bireylerin belirli bir anda sayılıp temel özelliklerinin kaydedilmesidir.'),
  ('Bir çocuğun ödevini zamanında bitirdiği için annesi tarafından övülmesi hangi tür yaptırımdır?', 'Resmi olmayan olumlu yaptırım', ['Resmi olumsuz yaptırım', 'Resmi olumlu yaptırım', 'Resmi olmayan olumsuz yaptırım'], 'Aile içinde övgü ve takdir, resmi bir kurum olmadan verilen olumlu yaptırımdır.'),
  ('Durkheim\'a göre bir toplumsal olguyu açıklarken hangi ilke izlenmelidir?', 'Toplumsal bir olgu başka toplumsal olgularla açıklanmalıdır', ['Toplumsal olgular yalnızca bireysel psikolojiyle açıklanmalıdır', 'Toplumsal olgular yalnızca iklimle açıklanmalıdır', 'Toplumsal olgular açıklanamaz, yalnızca betimlenebilir'], 'Durkheim, toplumsal olguların nedenlerinin bireysel bilinçte değil, önceki toplumsal olgularda aranması gerektiğini savunur.'),
  ('Bir taraftarın tuttuğu takım gol atınca sevinçle tribünde zıplaması Weber\'in eylem türlerinden hangisine en iyi uyar?', 'Duygusal eylem', ['Amaçsal-rasyonel eylem', 'Değer-rasyonel eylem', 'Geleneksel eylem'], 'Duygusal eylem, o anki duygu ve heyecanın yönlendirdiği, hesaplanmamış eylemdir.'),
  ('Comte\'a göre toplumsal düzenin ve ilerlemenin sağlanmasında hangi bilgi türü yol gösterici olmalıdır?', 'Gözlem ve deneye dayanan bilimsel bilgi', ['Yalnızca dinsel kutsal metinler ve din adamlarının yorumları', 'Soyut metafizik ilkeler', 'Kişisel sezgiler ve rüyalar'], 'Comte toplumun yeniden düzenlenmesinde pozitif, yani gözlem ve deneye dayalı bilimsel bilginin rehber olması gerektiğini savunmuştur.'),
  ('Ziya Gökalp\'e göre "medeniyet" neyi ifade eder?', 'Farklı milletlerin ortaklaşa ürettiği akla dayalı birikim', ['Bir millete özgü duygu ve değerler bütünü', 'Bir köyün geleneksel yaşam biçimi', 'Bir ailenin soy ağacı'], 'Gökalp\'e göre medeniyet uluslararası, yönteme ve akla dayalı bilim ve teknik birikimidir; hars ise millete özgüdür.'),
  ('Bir kişinin ilk kez kurallara aykırı davranması ile bu davranış nedeniyle "sapkın" damgası yedikten sonra bu kimliği benimseyip sapmayı sürdürmesi arasındaki ayrım hangi kavram çiftiyle anlatılır?', 'Birincil ve ikincil sapma', ['Mekanik ve organik sapma türleri', 'Yatay ve dikey sapma', 'Maddi ve manevi sapma'], 'Edwin Lemert\'e göre birincil sapma geçici bir kural ihlalidir; ikincil sapma ise etiketlenmenin ardından kişinin sapkın kimliği benimsemesidir.'),
  ('İki komşu ülkenin aralarındaki sınır sorununu silahlı mücadeleyle çözmeye çalışması hangi süreçtir?', 'Çatışma', ['Uzlaşma', 'Rekabet', 'Asimilasyon'], 'Tarafların birbirini etkisiz kılmaya ya da zarar vermeye yöneldiği karşıtlık ilişkisi çatışmadır.'),
  ('Toplumda yardımlaşma değerinin kurumsal bir yansıması olarak hangisi gösterilebilir?', 'Gönüllü dernekler ve vakıflar', ['Trafik cezaları', 'Moda dergileri', 'Rekabetçi satış kampanyaları ve indirimler'], 'Yardımlaşma değeri, yoksullara destek olan dernek ve vakıflar gibi örgütlerle kurumsal bir biçim kazanır.'),
  ('Toplumsal etkileşimin gerçekleşebilmesi için gerekli koşullardan biri hangisidir?', 'Taraflar arasında ortak semboller ve iletişim olması', ['Tarafların aynı yaşta olması', 'Tarafların aynı mesleği yapması', 'Tarafların aynı kentte ve aynı mahallede doğmuş olması'], 'Etkileşim için tarafların birbirini anlamasını sağlayan dil, jest ve semboller gibi ortak iletişim araçları gerekir.'),
  ('Toplumsal değişmenin "planlı" olarak gerçekleşmesine en uygun örnek hangisidir?', 'Devletin okuryazarlık seferberliği başlatması', ['Bir depremin bir kenti yıkması', 'Bir salgının kendiliğinden ve hızla yayılması', 'Bir modanın kendiliğinden yayılması'], 'Planlı değişme, belirli bir amaca ulaşmak için bilinçli olarak tasarlanıp uygulanan değişmedir.'),
  ('Bir ülkede zorunlu eğitim süresinin uzatılmasının toplumsal yapı üzerindeki olası etkilerinden biri hangisidir?', 'Gençlerin iş yaşamına daha geç girmesi', ['Doğum oranlarının hemen yükselmesi', 'Kentlerden köylere göçün başlaması', 'Ailenin bütün işlevlerini birden ve tamamen yitirmesi'], 'Eğitimde geçirilen sürenin artması gençlerin çalışma yaşamına ve evliliğe giriş yaşını erteleyebilir.'),
  ('Bir köyde okulun açılmasından sonra çocukların tarlada çalışmak yerine derse gitmesi aile içinde hangi değişime yol açabilir?', 'Ailenin ekonomik işbölümünün yeniden düzenlenmesi', ['Ailenin tamamen dağılması', 'Köyün nüfusunun birden ikiye katlanması', 'Toplumsal kontrolün tümüyle ortadan kalkması'], 'Çocukların iş gücünden çekilmesi, ailenin işleri nasıl paylaştığını değiştirir; bu, eğitim ile aile kurumu arasındaki bağı gösterir.'),
  ('Etnosentrizmin karşıtı sayılabilecek, başka bir kültürü kendi kültürünün üstünde görüp kendi kültürünü küçümseme eğilimine ne ad verilir?', 'Ksenosentrizm', ['Etnosentrizm', 'Asimilasyon', 'Kültürlenme'], 'Ksenosentrizm, yabancı bir kültürü üstün görerek kendi kültürünü değersizleştirme eğilimidir.'),
  ('Herbert Blumer\'in kalabalık türleri arasında, sokakta bir kazayı izlemek için toplanan insanlar hangi türe girer?', 'Rastlantısal (gelişigüzel) kalabalık', ['Geleneksel (alışılagelmiş) kurallı kalabalık', 'Etkin (eylemci) kalabalık', 'Dışavurumcu kalabalık'], 'Rastlantısal kalabalık, bir olay nedeniyle kısa süreliğine bir araya gelen ve aralarında çok az etkileşim bulunan insanlardan oluşur.'),
  ('Peter Berger ve Thomas Luckmann\'ın "Gerçekliğin Toplumsal İnşası" adlı eserinin temel savı hangisidir?', 'Toplumsal gerçekliğin insanların etkileşimleriyle kurulup sürdürüldüğü', ['Toplumsal gerçekliğin insanlardan tamamen bağımsız biçimde var olduğu', 'Toplumun yalnızca ekonomik yapıdan ibaret olduğu', 'Gerçekliğin yalnızca doğa bilimleriyle anlaşılabileceği'], 'Berger ve Luckmann, kurumların ve gündelik bilginin insanların etkileşimleriyle üretildiğini, zamanla nesnel bir gerçeklik gibi algılandığını savunur.'),
  ('Anne tarafından izlenen soy ve mirasın esas alındığı akrabalık sistemine ne ad verilir?', 'Anasoylu (matrilineal) sistem', ['Babasoylu (patrilineal) sistem', 'Babayerli (patrilokal) yerleşim', 'Yeni yerli (neolokal) yerleşim'], 'Anasoylu sistemlerde soy ve bazı haklar anne üzerinden aktarılır; Kuzey Amerika\'daki bazı yerli toplulukları buna örnektir.'),
  ('Bir toplumda gençlerin eşlerini ailelerinin değil, kendilerinin seçmesinin yaygınlaşması hangi toplumsal dönüşümle ilişkilidir?', 'Bireyselleşme ve kentleşme', ['Kast sisteminin güçlenmesi', 'Avcı-toplayıcılığa dönüş', 'Geniş ailenin yaygınlaşması'], 'Kentleşme, eğitim ve bireyselleşme, eş seçiminde ailenin etkisini azaltıp bireyin kararını öne çıkarır.'),
  ('Sosyolojinin uygulamalı bir dalı olarak toplum kalkınması, kent planlaması ve sosyal politikalara katkı sağlaması onun hangi yönünü gösterir?', 'Toplumsal sorunlara çözüm üretmeye katkı sunabilmesini', ['Yalnızca kuramsal tartışmalarla yetinmesini', 'Doğa olaylarını açıklamasını', 'Bireylerin kişisel sırlarını açığa çıkarmasını'], 'Sosyolojik bilgi, sorunların nedenlerini ortaya koyarak politika yapıcılara ve kurumlara yol gösterebilir.'),
  ('Aşağıdaki konulardan hangisi sosyolojinin alt dallarından "kriminoloji"nin ilgi alanına girer?', 'Suçun toplumsal nedenleri ve suç oranlarındaki değişim', ['Kentlerdeki trafik akışının mühendislik hesapları', 'Bir dilin ses yapısının çözümlenmesi', 'Bitkilerin fotosentez süreci'], 'Kriminoloji suçu, suçluluğu ve toplumun suça verdiği tepkileri inceleyen bir alandır.'),
  ('Bir kentin nüfusunun hızla artmasına karşın altyapı, konut ve istihdam olanaklarının aynı hızda artmaması hangi kavramla açıklanır?', 'Çarpık kentleşme', ['Soylulaştırma', 'Kırsal kalkınma politikası', 'Banliyöleşme'], 'Hızlı nüfus artışına karşın sanayileşme ve hizmetlerin yetersiz kalması plansız ve dengesiz bir kentleşmeye yol açar.'),
  ('Bir ülkede ortalama yaşam süresinin uzaması, emeklilik sistemleri açısından hangi sorunu doğurabilir?', 'Emekli sayısının çalışan sayısına oranla artması', ['Okul çağındaki nüfusun hızla ve sürekli artması', 'Kentleşmenin tamamen durması', 'Bebek ölüm hızının yükselmesi'], 'Yaşlı nüfusun artışı, prim ödeyen çalışanlara göre aylık alan emekli sayısını artırarak sistem üzerinde yük oluşturur.'),
  ('Bir araştırmacının ülkedeki bütün illerden, her ilin nüfusuyla orantılı sayıda kişiyi rastgele seçmesi hangi örnekleme türüdür?', 'Tabakalı örnekleme', ['Kartopu örneklemesi', 'Kolayda örnekleme', 'Amaçlı örnekleme'], 'Tabakalı örneklemede evren alt gruplara ayrılır ve her gruptan oranlı biçimde rastgele seçim yapılır.'),
  ('Bir toplumda kalıtsal unvanların, örneğin "lord" ya da "prens" gibi, kişiye ailesinden geçmesi hangi statü türüne örnektir?', 'Verilmiş statü', ['Kazanılmış statü', 'Ana statü', 'Statü tutarsızlığı'], 'Kalıtsal unvanlar kişinin çabasıyla değil, doğduğu aile nedeniyle elde edildiği için verilmiş statüdür.'),
  ('Eğitimin "yenilikçi" işlevine en uygun örnek hangisidir?', 'Üniversitelerde yapılan araştırmalarla yeni bilgi ve teknoloji üretilmesi', ['Çocuklara milli bayramların anlamının öğretilmesi', 'Öğrencilere okulda sıraya girmenin öğretilmesi', 'Öğrencilerin her gün aynı saatte okula gelmesi'], 'Eğitim kurumu yalnızca var olan bilgiyi aktarmakla kalmaz, araştırmalarla yeni bilgi üreterek toplumsal değişmeye katkı yapar.'),
  ('Gelir dağılımındaki eşitsizliği ölçmek için kullanılan ve değeri 0 ile 1 arasında değişen, 1\'e yaklaştıkça eşitsizliğin arttığını gösteren katsayı hangisidir?', 'Gini katsayısı', ['Doğurganlık hızı', 'Kentleşme oranı', 'Bağımlılık oranı'], 'Gini katsayısı 0 (tam eşitlik) ile 1 (tam eşitsizlik) arasında değer alır ve gelir dağılımı eşitsizliğini özetler.'),
];
